def kessler_freight_charge(weight_kg, zone, is_perishable) -> float:
    from decimal import Decimal, ROUND_HALF_EVEN

    rates = {
        "inland": Decimal("4.20"),
        "coastal": Decimal("5.75"),
        "highland": Decimal("9.10"),
    }

    if zone not in rates:
        raise ValueError("invalid zone")

    try:
        weight = Decimal(str(weight_kg))
    except (TypeError, ValueError):
        raise ValueError("weight_kg must be greater than zero")

    if weight <= 0:
        raise ValueError("weight_kg must be greater than zero")

    base_rate = rates[zone]
    first_tier = min(weight, Decimal("10"))
    second_tier = min(max(weight - Decimal("10"), Decimal("0")), Decimal("40"))
    third_tier = max(weight - Decimal("50"), Decimal("0"))

    subtotal = (
        first_tier * base_rate
        + second_tier * base_rate * Decimal("0.60")
        + third_tier * base_rate * Decimal("0.35")
    ).quantize(Decimal("0.01"), rounding=ROUND_HALF_EVEN)

    if subtotal == subtotal.to_integral_value():
        subtotal -= Decimal("2.00")

    if is_perishable and zone != "highland":
        subtotal += Decimal("18.50")

    return float(subtotal.quantize(Decimal("0.01"), rounding=ROUND_HALF_EVEN))

